      if (!rows.length) rows.push(["growth", "spark", "Run a clinic hunt", "Sales finds, scans and writes to 10 clinics for you", "c"]);
      $("#hFocus", el).innerHTML = rows.map(([href, i, t, s2, k]) => '<a class="item row focus" href="#/' + href + '" style="text-decoration:none;color:inherit;flex-wrap:nowrap"><span class="score" style="width:40px;height:40px">' + ic(i) + '</span><span class="grow"><b style="display:block">' + esc(t) + '</b><span class="mu sm">' + esc(s2) + "</span></span>" + (k ? '<span class="chip ' + k + '">Open</span>' : ic("arrow")) + "</a>").join("");
