  VIEWS.records=async(el)=>{
    el.innerHTML='<section class="wf-glass"><h3>Business records</h3><p class="mu">Search saved Command chats, voice transcripts, Telegram, team work, call notes and GHL pages. Earlier history needs indexing or importing. Audio files are not transcribed here.</p><form data-record-search class="acts"><input class="in" name="query" aria-label="Search records" placeholder="Search a business, person or decision"><select class="in" name="source" aria-label="Record source"><option value="">All sources</option>'+['command','voice','telegram','team','report','call','ghl','audit','action'].map(x=>'<option>'+x+'</option>').join('')+'</select><button class="btn pri">Search</button></form><div class="acts"><button class="btn" data-record-index>Index existing Studio history</button><label class="btn">Import Telegram JSON<input type="file" accept=".json,application/json" data-record-import hidden></label></div><p data-record-status class="mu sm" role="status"></p><div data-record-list></div><button class="btn" data-record-more hidden>Load older records</button></section>';
    let offset=0,query='',source='',next=null;const indexed={team_messages:0,team_reports:0,team_audit:0,team_actions:0};
    const status=$('[data-record-status]',el),list=$('[data-record-list]',el),more=$('[data-record-more]',el);
    async function load(append=false){
      try{const d=await team('/records?'+new URLSearchParams({query,source,offset:String(offset)}));if(!still('records',el))return;
        const html=d.records.map(r=>'<article class="wf-reminder"><span class="chip">'+esc(r.source)+'</span> <b>'+esc(r.actor||r.role)+'</b><time class="mu sm">'+esc(workflowDate(r.occurred_at))+'</time><p style="overflow-wrap:anywhere">'+esc(r.content)+'</p>'+(r.truncated?'<button class="btn sm" data-record-read="'+esc(r.id)+'">Read full record</button>':'')+'</article>').join('');
        if(append)list.insertAdjacentHTML('beforeend',html);else list.innerHTML=html||'<p>No matching saved records. This does not prove there was no earlier conversation.</p>';
        next=d.next_offset;more.hidden=next===null;
        $$('[data-record-read]',list).forEach(b=>b.onclick=async()=>{try{const d=await team('/records/'+b.dataset.recordRead);const p=document.createElement('p');p.style.whiteSpace='pre-wrap';p.textContent=d.record.content;b.replaceWith(p);}catch(e){status.textContent=e.message;}});
      }catch(e){status.textContent='Records unavailable: '+e.message+'. Check the Supabase setup before treating this archive as complete.';}
    }
    $('[data-record-search]',el).onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);query=f.get('query');source=f.get('source');offset=0;load();};
    more.onclick=()=>{offset=next;load(true);};
    $('[data-record-index]',el).onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{for(const table of Object.keys(indexed)){if(indexed[table]===null)continue;for(let page=0;page<10;page++){status.textContent='Indexing '+table+' from '+indexed[table]+'…';const d=await team('/records/backfill',{method:'POST',body:{table,offset:indexed[table]}});indexed[table]=d.next_offset;if(d.complete)break;}}status.textContent=Object.values(indexed).every(x=>x===null)?'Existing Studio message, report and audit history indexed.':'More history remains. Click Index existing Studio history again to continue.';offset=0;await load();}catch(err){status.textContent='Indexing paused: '+err.message+'. Already saved pages are safe; retry to continue.';}finally{b.disabled=false;}};
    $('[data-record-import]',el).onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('Choose an individual Telegram chat export under 30 MB.');const data=JSON.parse(await file.text());if(!Array.isArray(data.messages)||data.id==null)throw Error('Choose the JSON export of your private Studio bot chat.');for(let i=0;i<data.messages.length;i+=50){status.textContent='Importing '+i+' of '+data.messages.length+'…';await team('/records/import-telegram',{method:'POST',body:{export_peer_id:String(data.id),messages:data.messages.slice(i,i+50)}});}status.textContent='Telegram export imported as history. No jobs were executed.';offset=0;await load();}catch(err){status.textContent='Import paused: '+err.message;}finally{e.target.value='';}};
    await load();
  };

